    static class Solver {
        public void solve(BufferedReader br, PrintWriter out) throws IOException {
            int n = Integer.parseInt(br.readLine());
            String s = br.readLine();
            int wins = 0, maxLen = 0;
            int i = 0, j = 0;
            while (s.contains("__")) s = s.replace("__", "_");
            n = s.length();

            if (s.charAt(i) == '(') {
                while (j < n && s.charAt(j) != ')') j++;
                if (j < n && s.charAt(j) == ')') {
                    String temp = s.substring(i + 1, j);
                    if (!temp.contains("_") && temp.length() > 0)
                        wins++;
                    else {
                        String[] tokens = temp.split("_");
                        wins += tokens.length;
                    }
                    i = j + 1;
                }
            }

            for (int k = 0; k < n; k++) {
                if (s.charAt(k) == '(') {
                    int l = k;
                    while (l < n && s.charAt(l) != ')') l++;
                    if (l < n && s.charAt(l) == ')') {
                        String temp = s.substring(k + 1, l);
                        if (!temp.contains("_") && temp.length() > 0)
                            wins++;
                        else {
                            String[] tokens = temp.split("_");
                            wins += tokens.length;
                        }
                        k = l;
                    }
                }
            }

            while (s.contains("(") || s.contains(")")) {
                s = s.replaceAll("\\([^\\(]*\\)", "_");
            }

            String[] parts = s.split("_");
            for (String part : parts) {
                if (part.length() > maxLen)
