#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string s;
    cin >> s;
    int wins = 0, maxLen = 0;

    // Replace all "__" with "_"
    while (s.find("__") != string::npos) {
        size_t pos = s.find("__");
        s.replace(pos, 2, "_");
    }
    n = (int)s.length();

    int i = 0, j = 0;
    if (s[i] == '(') {
        j = i;
        while (j < n && s[j] != ')') j++;
        if (j < n && s[j] == ')') {
            string temp = s.substr(i + 1, j - i - 1);
            if (temp.find('_') == string::npos && (int)temp.length() > 0)
                wins++;
            else {
                int count = 1;
                for (char c : temp) {
                    if (c == '_') count++;
                }
                wins += count;
            }
            i = j + 1;
        }
    }

    for (int k = 0; k < n; k++) {
        if (s[k] == '(') {
            int l = k;
            while (l < n && s[l] != ')') l++;
            if (l < n && s[l] == ')') {
                string temp = s.substr(k + 1, l - k - 1);
                if (temp.find('_') == string::npos && (int)temp.length() > 0)
                    wins++;
                else {
                    int count = 1;
                    for (char c : temp) {
                        if (c == '_') count++;
                    }
                    wins += count;
                }
                k = l;
            }
        }
    }

    // Remove all parentheses and their contents
    while (true) {
        size_t start_pos = s.find('(');
        size_t end_pos = s.find(')');
        if (start_pos == string::npos || end_pos == string::npos || end_pos < start_pos)
            break;
        s.replace(start_pos, end_pos - start_pos + 1, "_");
    }

    // Split by '_'
    stringstream ss(s);
    string part;
    while (getline(ss, part, '_')) {
        if ((int)part.length() > maxLen)
            maxLen = part.length();
    }

    cout << maxLen << " " << wins << "\n";

    return 0;
}
